import{_ as a,o as i,c as l,ai as o}from"./chunks/framework.Ba-VnP44.js";const A=JSON.parse('{"title":"用 AI 辅助写技术文章","description":"","frontmatter":{},"headers":[],"relativePath":"ai/creation/ai-writing.md","filePath":"ai/creation/ai-writing.md"}'),e={name:"ai/creation/ai-writing.md"};function r(d,t,u,h,n,q){return i(),l("div",null,[...t[0]||(t[0]=[o('<h1 id="用-ai-辅助写技术文章" tabindex="-1">用 AI 辅助写技术文章 <a class="header-anchor" href="#用-ai-辅助写技术文章" aria-label="Permalink to “用 AI 辅助写技术文章”">​</a></h1><h2 id="场景与问题" tabindex="-1">场景与问题 <a class="header-anchor" href="#场景与问题" aria-label="Permalink to “场景与问题”">​</a></h2><p>做了几年开发，脑子里其实有不少能写的东西：一个坑的排查过程、一套自己摸索出来的方案、一次重构的经验。但真正动笔时往往卡住——</p><ul><li>白天写代码，晚上打开编辑器，从零敲标题、列大纲，写两段就疲了，一篇文章拖两三周；</li><li>觉得自己写的&quot;太干&quot;，没有铺垫没有过渡；又怕 AI 帮忙写之后变成&quot;水文&quot;，一眼机器味；</li><li>技术文章最怕事实出错：版本号、命令参数、API 行为记错了，读者照着做踩坑，比不写还伤信任；</li><li>看别人用 AI 十分钟出一篇，自己用却全是套话：&quot;在当今快速发展的技术领域……&quot;，发出去不像自己写的。</li></ul><p>核心矛盾是：<strong>AI 写得快但写得假，自己写得真但写得慢</strong>。解法不是二选一，而是把选题、大纲、初稿、润色拆开，明确哪一步归人、哪一步归 AI。</p><h2 id="做法" tabindex="-1">做法 <a class="header-anchor" href="#做法" aria-label="Permalink to “做法”">​</a></h2><h3 id="_1-分工原则-ai-打骨架和苦工-人出判断和细节" tabindex="-1">1. 分工原则：AI 打骨架和苦工，人出判断和细节 <a class="header-anchor" href="#_1-分工原则-ai-打骨架和苦工-人出判断和细节" aria-label="Permalink to “1. 分工原则：AI 打骨架和苦工，人出判断和细节”">​</a></h3><p>我的固定分工是四步：</p><table tabindex="0"><thead><tr><th>环节</th><th>谁主导</th><th>具体做什么</th></tr></thead><tbody><tr><td>选题</td><td>人</td><td>从自己最近踩的坑、解决的问题里挑，AI 只用来发散和补充角度</td></tr><tr><td>大纲</td><td>人 + AI</td><td>我先写 3-5 个要点，让 AI 补全结构、提反问，我删掉不想要的</td></tr><tr><td>初稿</td><td>人写核心，AI 填过渡</td><td>技术结论、案例数据、命令代码自己写；背景铺垫、段间过渡可以让 AI 起草</td></tr><tr><td>润色</td><td>AI 初筛 + 人终审</td><td>AI 查冗余和口语病，人把结论、措辞改回自己的语气</td></tr></tbody></table><p>关键在于不要让 AI 从标题直接生成全文。那样得到的是一篇&quot;关于 XX 的通用文章&quot;，去掉标题换成任何技术都成立，等于没写。</p><h3 id="_2-选题与大纲-让-ai-当-编辑-而不是-作者" tabindex="-1">2. 选题与大纲：让 AI 当&quot;编辑&quot;而不是&quot;作者&quot; <a class="header-anchor" href="#_2-选题与大纲-让-ai-当-编辑-而不是-作者" aria-label="Permalink to “2. 选题与大纲：让 AI 当&quot;编辑&quot;而不是&quot;作者&quot;”">​</a></h3><p>选题阶段我会把最近的工作记录、issue 列表丢给 AI，问三个问题：</p><ul><li>这里面哪些点是别的开发者也会遇到的？</li><li>哪些适合写成文章，哪些只够发一条短动态？</li><li>同类主题已经烂大街的角度有哪些，我这个有什么不同？</li></ul><p>大纲阶段，先自己列要点（这一步不能省，它逼你确认&quot;我到底想说什么&quot;），再让 AI 挑结构问题：&quot;第三点和第二点是不是重复了？&quot;&quot;读者到这里会不会缺前置知识？&quot;。AI 补充的框架可以留，但每个小节的标题必须是具体结论，不是&quot;相关实践&quot;这种空壳。</p><h3 id="_3-初稿-带着素材喂-ai-而不是空手要文章" tabindex="-1">3. 初稿：带着素材喂 AI，而不是空手要文章 <a class="header-anchor" href="#_3-初稿-带着素材喂-ai-而不是空手要文章" aria-label="Permalink to “3. 初稿：带着素材喂 AI，而不是空手要文章”">​</a></h3><p>写初稿时，我提供的不是&quot;帮我写一篇 XX&quot;，而是打包素材：</p><ul><li>自己的真实案例：报错截图、当时的代码片段、排查步骤、最终结论；</li><li>我口述的核心观点，哪怕只是三五句话；</li><li>目标读者（新手 / 有经验的后端），决定解释到什么深度。</li></ul><p>AI 负责把素材组织成通顺的段落。凡是涉及&quot;我&quot;的部分——当时怎么想的、走了什么弯路、为什么最后选了方案 B——必须自己写，这是文章的辨识度所在。</p><h3 id="_4-事实核查-发布前的硬性-checklist" tabindex="-1">4. 事实核查：发布前的硬性 Checklist <a class="header-anchor" href="#_4-事实核查-发布前的硬性-checklist" aria-label="Permalink to “4. 事实核查：发布前的硬性 Checklist”">​</a></h3><p>技术文章的错误成本极高，我发布前固定过一遍：</p><ul><li>[ ] 所有版本号、命令参数、配置项，对着官方文档或本地环境核一遍；</li><li>[ ] 代码片段实际跑过（至少在最小可复现环境跑过），不是 AI&quot;看起来对&quot;的代码；</li><li>[ ] AI 给出的引用、数据、&quot;据说&quot;类结论，逐条查原始来源；查不到的直接删；</li><li>[ ] 数量词复查：&quot;快了 10 倍&quot;是实测还是感觉？感觉就改成定性描述。</li></ul><p>AI 会自信地编造 API、编造基准数据，这是它最危险的地方。<strong>凡是能被读者复现验证的内容，默认不可信，必须自己验。</strong></p><h3 id="_5-去-ai-味-最后一遍用自己的话重写" tabindex="-1">5. 去 AI 味：最后一遍用自己的话重写 <a class="header-anchor" href="#_5-去-ai-味-最后一遍用自己的话重写" aria-label="Permalink to “5. 去 AI 味：最后一遍用自己的话重写”">​</a></h3><p>初稿成形后，我会做一轮&quot;降 AI 味&quot;处理：</p><ul><li>删掉所有空洞开场：&quot;随着……的发展&quot;、&quot;在当今……时代&quot;，直接从问题切入；</li><li>把排比工整的三段式小标题改成具体的话（&quot;三个最佳实践&quot;→&quot;先加索引，再分页，最后才考虑缓存&quot;）；</li><li>每隔几段插入一句真实的、带情绪的判断：&quot;这里我卡了整整一天&quot;、&quot;这个方案我后来后悔了&quot;；</li><li>结尾不升华，给出明确的下一步：可以试的命令、可以避的坑。</li></ul><p>最狠也最有效的一招：<strong>对着稿子用自己的话重讲一遍，讲不顺的地方就是没想清楚的地方</strong>，回去改那段。AI 味的本质不是用词，是思维缺席。</p><h2 id="关键要点" tabindex="-1">关键要点 <a class="header-anchor" href="#关键要点" aria-label="Permalink to “关键要点”">​</a></h2><ul><li>分工核心：选题和观点归人，组织和过渡归 AI，事实核查谁都替代不了人；</li><li>不要让 AI 从零生成全文，要喂真实素材（案例、代码、口述观点），AI 只负责成文；</li><li>涉及技术事实的内容默认不可信：版本、参数、性能数据、引用来源逐条核实；</li><li>文章的辨识度在个人细节里：真实踩坑、具体取舍、带判断的句子；</li><li>去 AI 味 = 删套话 + 打散工整结构 + 插入真实情绪 + 用自己的话重讲一遍。</li></ul><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h2><p>AI 辅助写技术文章，效率提升来自它接管了&quot;组织素材、生成过渡、润色语言&quot;这类苦工；质量保障来自你坚持&quot;观点自己出、案例自己给、事实自己查&quot;。流程跑顺之后，一篇过去要写两周的文章可以压到两三个晚上，而读起来依然明显是你的风格——这正是把 AI 用对了的样子。</p>',30)])])}const c=a(e,[["render",r]]);export{A as __pageData,c as default};
